[97970] = {"Основы походной жизни: горное дело", {"Поговорите с Мессаной Поднебесный Ветер в деревне Шен'дар, чтобы научиться создавать предмет для лагеря из вашей профессии, когда продемонстрируете свои навыки в ней."}},
[97971] = {"Основы походной жизни: снятие шкур", {"Поговорите с Мендалассом Живительный Эликсир в деревне Шен'дар, чтобы научиться создавать предмет для лагеря из вашей профессии, когда продемонстрируете свои навыки в ней."}},
[97973] = {"Основы походной жизни: портняжное дело", {"Поговорите с Талин Сверкающая Нить в деревне Шен'дар, чтобы научиться создавать предмет для лагеря из вашей профессии, когда продемонстрируете свои навыки в ней."}},
[97977] = {"Зов природы", {"Соберите 4 |4тотем:тотема:тотемов; племени Кривой Сосны и принесите их Тариндрелле."}},
[97979] = {"Дары богини", {"Примените способности \"Свет Элуны\" и \"Слиться с тенью\"."}},
[98013] = {"Разрастающиеся силы", {"Убейте 12 |4мирмидона:мирмидонов:мирмидонов;, 8 |4колдунью:колдуний:колдуний; и 6 |4воина:воинов:воинов; из клана Гремучей чешуи по просьбе Арбала из Рощи Древних."}},
[98021] = {"Путь на Сторожевой холм", {"Поговорите с Грианом Камнегривом в Западном крае."}},
[98024] = {"Путь к Перекрестку", {"Поговорите с Тхорком в Перекрестке, что в Степях."}},
[98025] = {"РАЗЫСКИВАЕТСЯ: Джай'ванель", {"Найдите и убейте сову Джай'ванель и добудьте одно из ее перьев. Эту черную сову видели к северу от руин Амет'Арана у подножия горы. Доложите о смерти Джай'ванель часовому Глинде Нал'Шии в Аубердине."}},
[98028] = {"Барон Мориний", {"Принесите помутневшую водяную сферу Ону в Рощу Древних на Темных берегах."}},
[98042] = {"Кто старое помянет...", {"Добудьте несравненное око у сумеречного послушника или сумеречного лиходея у Меча Властителя на Темных берегах и найдите в Аубердине того, кто заберет его у вас."}},
[98046] = {"Корона земли", {"Принесите опустошенный сосуд Ларии в храм Луны в Дарнассе."}},
[98065] = {"Корона земли", {"Принесите частицы Лунного колодца Тиранде Шелест Ветра в храм Луны в Дарнассе."}},
[98067] = {"Глаза часовых", {"Разместите сов-часовых возле входа в глубины крепости Кенария, дарнасского банка, таверны на Террасе Ремесленников и городских ворот по просьбе часового Далии Солнечный Клинок из храма Луны в Дарнасе."}},
[98093] = {"Полевая зачистка", {"Убейте 7 |4грозового ящера:грозовых ящеров:грозовых ящеров; и 7 |4многозубого ловца:многозубых ловцов:многозубых ловцов; вокруг, чтобы Сулхаса смогла спуститься с дерева."}},
[98094] = {"Помощь разведчикам", {"Верховный палач Дарталия хочет, чтобы вы доставили новые указания стражу смерти Масоджу на юг от Мельницы Таррен, рядом с Дун Гароком."}},
[98197] = {"Трофеи войны", {"Добудьте для Валстага Сталезуба 6 ед. каз-моданской древесины и 30 ед. каз-моданского железа в Гавани Менетилов."}},
[98208] = {"Небесный цветок", {"Добудьте Норд'эль для Силессы Шепот Сумрака в Гавани Менетилов."}},
[98247] = {"Транспортная этикетка", {"Доставьте транспортную этикетку кому-нибудь в \"Азеротском торговом управлении\" в Красногорье."}},
[98248] = {"Транспортная этикетка", {"Доставьте транспортную этикетку кому-нибудь на торговом посту \"Дуротарского снабжения и логистики\" рядом с Перекрестком в Степях."}},
[98282] = {"Опасная алхимия", {"Добудьте нелопнувшую железу хищника в пещере Тельгена для Кейтлин Грассман в Гавани Менетилов."}},
[98285] = {"Основы походной жизни: инженерное дело", {"Поговорите со странным отшельником в Теневейном лесу, чтобы показать свои навыки и научиться создавать предмет для лагеря, соответствующий вашей профессии."}},
[98286] = {"Основы походной жизни: наложение чар", {"Поговорите с Насаланной Певицей Ветра в деревне Шен'дар, чтобы научиться создавать предмет для лагеря из вашей профессии, когда продемонстрируете свои навыки в ней."}},
[98298] = {"Безрассудство Аругала", {"Принесите 6 |4ошметок:ошметка:ошметков; воргена Далару Ткачу Рассвета в Гробницу."}},
[98299] = {"Остановить заражение", {"Убейте 5 |4больного беженца:больных беженцев:больных беженцев; и 5 |4изможденного беженца:изможденных беженцев:изможденных беженцев; по просьбе Далара Ткача Рассвета в Гробнице."}},
[98319] = {"Зачистка горы", {"Разыщите горного пехотинца Корнелия в Серой берлоге по просьбе горного пехотинца Гретхен."}},
[98321] = {"Груз Огнива", {"Добудьте 8 |4груз:груза:грузов; Огнива из Серой берлоги для Тогнуса Огниво в Караносе."}},
[98322] = {"Зачистка горы", {"Встретьтесь с горным пехотинцем Гретхен к западу от Караноса."}},
[98323] = {"Зачистка горы", {"Вернитесь с отчетом горного пехотинца Гретхен к Сениру Белобороду в Каранос."}},
[98326] = {"Ледяной Вой", {"Убейте Ледяного Воя и верните мешок рыбы Гретте Гантер в поселке Пивоваров."}},
[98340] = {"Дух Великой Кошки", {"Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне."}},
[98341] = {"Дух великой рожденной ветром кошки", {"Разыщите аватару Сэйлинан в южной части Лунной поляны и узнайте, чему она хочет научить вас касательно природы рожденной ветром кошки."}},
[98362] = {"К Громовому Утесу", {"Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин."}},
[98372] = {"Бесславная участь", nil},
[98386] = {"Лесопилка Альтера", {"Убейте 12 |4крупного тарантула:крупных тарантулов:крупных тарантулов; и уничтожьте 6 |4яйцо:яйца:яиц; тарантулов на лесопилке Альтера по просьбе штейгера Ослоу, который находится в Красногорье."}},
[98387] = {"Блокада Черной Горы", {"Принесите маршалу Маррису в Приозерье 10 затупившихся в бою топоров."}},
[98389] = {"Свет во тьме", {"Освободите 6 |4жертву:жертвы:жертв; в паутине в низине Ночных Пут по просьбе Арамиса Хаммерхенда, находящегося в Похоронном Звоне."}},
[98391] = {"Сестринство Элуны", {"Поговорите с сестрой Аквинной в Дарнассе."}},
[98392] = {"Тьма на поляне", {"Принесите амулет злобного визга, амулет повелительницы ветра Гаэдрессы и амулет матери-ведьмы Арисы часовому Арании Проблеск Солнца на Поляну Оракула."}},
[98393] = {"Дух Великой Кошки", {"Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне."}},
[98397] = {"В Дарнас", {"Вернитесь в Дарнас и поговорите с Матренгилом Медвежья Лапа в анклаве Кенария."}},
[98398] = {"Древо-оракул", {"Найдите находящуюся неподалеку кору Древа-оракула, чтобы получить его послание."}},
[98403] = {"Извращенная ненависть", {"Убейте 8 |4оскверненного чащобного тенетника:оскверненных чащобных тенетников:оскверненных чащобных тенетников;, а также добудьте зрелый мох Скверны у Зеторра Злобного и принесите его Таллонкаю Гибкий Корень в Доланаар."}},
[98404] = {"Дух великой рожденной ветром кошки", {"Добудьте реликвию клыка, реликвию когтя и реликвию тихой тени в кельях Малфуриона, а затем отнесите их аватаре Сэйлинана."}},
[98407] = {"Демонстрация силы", {"Добудьте 5 |4шипастый ошейник:шипастых ошейника:шипастых ошейников; у твердозубов из стаи Красногорья для заместителя судьи Фелдона, который находится недалеко от Приозерья."}},
[98423] = {"Соглашение о взаимопонимании", {"Доставьте Договор о взаимопонимании Магни Бронзобороду в Стальгорн."}},
[98424] = {"Заметки Шумовика", {"Соберите оставшиеся страницы записей бригадира Шумовика в шахте Торговой Компании и отнесите их Морину Ловцу Облаков, которого можно найти неподалеку от деревни Кровавого Копыта."}},
[98427] = {"Прекращение работ", {"Отнесите ключ от лесопила Морину Ловцу Облаков возле деревни Кровавого Копыта."}},
[98430] = {"Дальноходы", {"Помогите Периту Штормовое Копыто сбежать с утеса Бледногривов и сообщите о том, что он в безопасности, Кэрну Кровавое Копыто в Громовом Утесе."}},
[98435] = {"Донесение Громового Рога", {"Принесите донесение Громового Рога верховному друиду Хамуулу Руническому Тотему в Громовой Утес."}},
[98461] = {"Безответная любовь", {"Отнесите записку Холли Таррелу Камнепряду, живущему неподалеку от Гавани Менетилов в Болотине."}},
[98512] = {"Ал'акетские убийцы", {"Устраните 10 ал'акетских убийц на Шен'дарском нагорье."}},
[98545] = {"Письмо Леонида", {"Отнесите запечатанное письмо Гликсу Ксиззиксу в Подгород."}},
[98574] = {"Освященный меморандум", {"Изучите освященный меморандум, а затем найдите в Старой Наковальне Бранстока Халдера и поговорите с ним."}},
[98575] = {"Оскверненная скрижаль", {"Прочтите, что написано на оскверненной скрижали, и поговорите с Нартоком в Логове в Долине Испытаний."}},
[98581] = {"Архаичная руна", {"Прочтите архаичную руну и поговорите с Тео Громовым Молотом в Старой Наковальне."}},
[98601] = {"Трудный путь", {"Прочитайте освященный свиток и поговорите с Арамисом Хаммерхендом в церкви Похоронного Звона."}},
[98738] = {"Благословение духа Великой Рожденной Ветром Кошки", {"Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне."}},
[99046] = {"Пропавшая бегунья", {"Найдите часовую Эралию Тень Листвы на дороге, ведущей к Поляне Оракула."}},
[99047] = {"Еще не мертва", {"Обратитесь к Бьянси в Доланааре за помощью для часовой Эралии Тень Листвы."}},
[99048] = {"Пропавшая Длань", {"Найдите Хеглан Подбитый Глаз к северу от крепости Тирагард."}},
[99049] = {"Опасность из глубин", {"Найдите следы созданий, напавших на Хеглан Подбитый Глаз."}},
[99050] = {"Дары Древа", {"Добудьте 6 |4росистую ветвь:росистые ветви:росистых ветвей; плеточников, пустую колбу и освежающую ключевую воду по просьбе Бьянси в Доланааре."}},
[99051] = {"Опасность из глубин", {"Добудьте 9 |4спинной плавник:спинных плавника:спинных плавников; наг."}},
[99052] = {"Опасность из глубин", {"Убейте морского великана на северном берегу Дуротара и принесите доказательство."}},
[99053] = {"Побег из Бен'этиль", {"Помогите часовому Линессе Вечернице выбраться из обители Бен'этиль и доложите о ее спасении часовому Кире Песнь Звезд в Доланааре."}},
[99073] = {"Облегчение страданий", {"Отнесите бальзам из воды плеточников часовой Эралии Тень Листвы на дорогу, ведущую к Древу-оракулу."}},
[99079] = {"Дальноход Мала", {"Найдите дальнохода Малу Дальний Ветер к востоку от деревни Кровавого Копыта у границы Мулгора."}},
[99080] = {"Прочь из нашей земли", {"Убейте 6 |4кентавра:кентавров:кентавров; и 4 |4гонца:гонцов:гонцов; из племени Галак, а также принесите голову Керака Разорителя Бейну Кровавое Копыто."}},
[99081] = {"Мрачные вести", {"Отнесите отчет дальнохода Малы храбрецу Вольному Охотнику в деревню Кровавого Копыта."}},
[99082] = {"Верховный вождь", {"Добейтесь аудиенции у верховного вождя Кэрна Кровавое Копыто в Громовом Утесе."}},
[99101] = {"Наш древний враг", {"Отнесите отчет дальнохода Малы Бейну Кровавое Копыто."}},
[99108] = {"Учебный поединок", {"Победите в дуэли трех других игроков или воинов-учеников по просьбе Танга Каменное Копыто."}},
[99123] = {"Затерявшаяся в тенях", {"Помогите Пал'джу выбраться с утеса Колкара и сообщите об этом мастеру Ворналу в деревне Сен'джин."}},
[99127] = {"Путаница с сетями", {"Проверьте рыболовные ловушки на озере Хрустальном."}},
[99128] = {"Склизкая угроза", {"Убейте 7 |4мурлока:мурлоков:мурлоков; и 4 |4речного мурлока-бегуна:речных мурлоков-бегунов:речных мурлоков-бегунов; на озере Хрустальном, а затем вернитесь к Джейсону Матерсу."}},
[99129] = {"Нелюбитель мурлоков", {"Поговорите с Реми Повторюхом о проблемах Джейсона с мурлоками."}},
[99130] = {"Заманчивое предложение", {"Добудьте 6 |4сосуд:сосуда:сосудов; звериной крови и 18 |4лепесток:лепестка:лепестков; закатнолиста для приманки на мурлоков, а затем вернитесь к Реми Повторюху в Златоземье."}},
[99131] = {"Наживка для успеха", {"Вернитесь к Джейсону Матерсу."}},
[99134] = {"Наказание", {"Покарайте 5 |4стража:стражей:стражей; смерти по распоряжению палача Зуганда."}},
[99141] = {"Терпение", {"Заберите донесения у стража смерти Диллинджера, стража смерти Кристофа и Гордо по просьбе палача Зуганда."}},
[99142] = {"Гроб-трава", {"Соберите 5 |4пучок:пучка:пучков; гроб-травы по просьбе младшего аптекаря Холланда."}},
[99143] = {"Бутылки и безделушки", {"Соберите 6 |4обломок:обломка:обломков; блестящего хлама в лагере мурлоков неподалеку."}},
[99144] = {"В поисках убежища", {"Помогите Барету Рассветная Скала выбраться с заставы Алого ордена и расскажите Шари Стилвелл в Брилле о том, что он в безопасности."}},
[99152] = {"Как наверху, так и внизу", {"Добудьте 6 |4тускло светящуюся кость:тускло светящиеся кости:тускло светящихся костей; по просьбе Хильды Сокрушительницы."}},
[99153] = {"Последний осколок", {"Найдите спрятанный осколок кристалла под Тенедолом по просьбе Эфрама Барбаро."}},
