[99158] = {"Рассвет в горах", {"Отнесите ящик со свечами отцу Гавину в сторожку у заснеженной сосны."}},
[99159] = {"В поисках тепла", {"Заготовьте 14 |4охапку:охапки:охапок; дров."}},
